import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(`${runtime}/package.json`);
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(`${runtime}/linux.json`,'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(`${runtime}/display`,'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:5173',{waitUntil:'load'});
await page.locator('#play-button').click();
await page.waitForTimeout(3000);
await page.keyboard.down('KeyW');
for(let i=0;i<14;i++){
 await page.waitForTimeout(1000);
 const state=await page.evaluate(()=>({time:document.querySelector('#timer-value').textContent,progress:document.querySelector('#progress-fill').style.width,stage:document.querySelector('#stage-value').textContent,banner:document.querySelector('#toast').textContent,shown:document.querySelector('#toast').className}));
 console.log(i+1,JSON.stringify(state));
}
await page.keyboard.up('KeyW');
console.log('errors',JSON.stringify(errors));
await page.screenshot({path:'/tmp/opencode/crown-rush-test.png'});
await browser.close();

