function updateHazards(dt){for(const h of spinners){h.pivot.rotation.y+=dt*Math.PI/4*h.sign;if(Math.abs(player.z-h.z)<11&&Math.abs(player.x)<11&&player.grounded)player.vx+=Math.sin(h.pivot.rotation.y)*dt*1.7}
