  game.time+=dt;stepRunner(player,dt,true);for(const b of bots)stepRunner(b,dt,false);
  if(game.bannerTimer>0){game.bannerTimer-=dt;if(game.bannerTimer<=0)$('checkpoint-banner').classList.remove('show')}
